// HasLatestEvidence applies the HasEdge predicate on the "latest_evidence" edge.
func HasLatestEvidence() predicate.WorkDecisionTargetEvaluation {
	return predicate.WorkDecisionTargetEvaluation(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, LatestEvidenceTable, LatestEvidenceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLatestEvidenceWith applies the HasEdge predicate on the "latest_evidence" edge with a given conditions (other predicates).
func HasLatestEvidenceWith(preds ...predicate.Evidence) predicate.WorkDecisionTargetEvaluation {
	return predicate.WorkDecisionTargetEvaluation(func(s *sql.Selector) {
		step := newLatestEvidenceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkDecisionTargetEvaluation) predicate.WorkDecisionTargetEvaluation {
	return predicate.WorkDecisionTargetEvaluation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkDecisionTargetEvaluation) predicate.WorkDecisionTargetEvaluation {
	return predicate.WorkDecisionTargetEvaluation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkDecisionTargetEvaluation) predicate.WorkDecisionTargetEvaluation {
	return predicate.WorkDecisionTargetEvaluation(sql.NotPredicates(p))
}
